/**
 * Busca la retencion de un metodo por texto de la fuente (ej. "VEG,GREENS,STEAMED").
 * Devuelve null si no hay coincidencia.
 */
export function findRetention(sourceText) {
  const q = sourceText?.toUpperCase()?.trim();
  return NUTRIENT_RETENTION.find((r) => r.source.toUpperCase() === q) ?? null;
}

/**
 * Los metodos mas y menos conservadores para una familia de alimento.
 * `family` es texto libre del campo source, por ejemplo "VEG" o "CHICKEN".
 */
export function rankMethods(family) {
  const f = family.toUpperCase();
  return NUTRIENT_RETENTION
    .filter((r) => r.source.toUpperCase().startsWith(f))
    .map(({ es, source, min, mean }) => ({ es, source, min, mean }));
}
